import { IMatrixProfile, MatrixClient, MatrixEvent, RoomMember, RoomMemberEvent } from "matrix-js-sdk/src/matrix";
import { logger } from "matrix-js-sdk/src/logger";

import { LruCache } from "../utils/LruCache";

const PROFILE_CACHE_CAPACITY = 500;

/**
 * Cached access to user profiles. Keeps two LRU caches: one for all fetched profiles and
 * one for profiles of known users (users sharing at least one room with the current user).
 * Cached entries are invalidated when membership events report changed profile values.
 */
export class UserProfilesStore {
    private readonly profiles = new LruCache<string, IMatrixProfile | null>(PROFILE_CACHE_CAPACITY);
    private readonly knownProfiles = new LruCache<string, IMatrixProfile | null>(PROFILE_CACHE_CAPACITY);

    public constructor(private readonly client: MatrixClient) {
        this.client.on(RoomMemberEvent.Membership, this.onRoomMembershipEvent);
    }

    private onRoomMembershipEvent = (event: MatrixEvent, member: RoomMember): void => {
        const userId = member.userId;
        const avatarUrl = member.getMxcAvatarUrl();
        const displayName = member.rawDisplayName;

        for (const cache of [this.profiles, this.knownProfiles]) {
            const profile = cache.get(userId);
            if (!profile) continue;
            if (profile.displayname !== displayName || profile.avatar_url !== avatarUrl) {
                cache.delete(userId);
            }
        }
    };

    /**
     * Synchronously get a profile from the all-profiles cache.
     * @returns the profile if cached, null if it does not exist, undefined if not cached.
     */
    public getProfile(userId: string): IMatrixProfile | null | undefined {
        return this.profiles.get(userId);
    }

    /**
     * Synchronously get a profile from the known-users cache.
     * @returns the profile if cached, null if it does not exist, undefined if not cached.
     */
    public getOnlyKnownProfile(userId: string): IMatrixProfile | null | undefined {
        return this.knownProfiles.get(userId);
    }

    /**
     * Fetch a profile from the API and store it in the all-profiles cache.
     * Returns null if the profile does not exist or cannot be fetched.
     */
    public async fetchProfile(userId: string): Promise<IMatrixProfile | null> {
        try {
            const profile = await this.client.getProfileInfo(userId);
            this.profiles.set(userId, profile);
            return profile;
        } catch (e) {
            logger.warn(`Unable to fetch profile for ${userId}`, e);
            this.profiles.set(userId, null);
            return null;
        }
    }

    /**
     * Fetch a profile for a known user (one sharing a room with the current user) and store it
     * in the known-users cache. Returns undefined without any API request if the user is unknown.
     */
    public async fetchOnlyKnownProfile(userId: string): Promise<IMatrixProfile | null | undefined> {
        if (!this.isKnownUser(userId)) return undefined;

        try {
            const profile = await this.client.getProfileInfo(userId);
            this.knownProfiles.set(userId, profile);
            return profile;
        } catch (e) {
            logger.warn(`Unable to fetch profile for known user ${userId}`, e);
            this.knownProfiles.set(userId, null);
            return null;
        }
    }

    private isKnownUser(userId: string): boolean {
        return this.client.getRooms().some((room) => !!room.getMember(userId));
    }
}
