+import { logger } from "matrix-js-sdk/src/logger";
+
+interface LruNode<K, V> {
+    key: K;
+    value: V;
+    prev: LruNode<K, V> | null;
+    next: LruNode<K, V> | null;
+}
+
+/**
+ * Least Recently Used cache initialized with a capacity. Drops the least recently used items when over capacity.
+ * Entries are stored in a native Map keyed by the raw cache key (so values() follows insertion order),
+ * while a doubly linked list tracks recency for eviction.
+ */
+export class LruCache<K, V> {
+    private readonly map = new Map<K, LruNode<K, V>>();
+    // head = least recently used, tail = most recently used
+    private head: LruNode<K, V> | null = null;
+    private tail: LruNode<K, V> | null = null;
+
+    public constructor(private readonly capacity: number) {
+        if (capacity < 1) {
+            throw new Error("Cache capacity must be at least 1");
+        }
+    }
+
+    /**
+     * Check whether the cache contains an item under this key. Marks the item as most recently used.
+     */
+    public has(key: K): boolean {
+        const node = this.map.get(key);
+        if (!node) return false;
+        this.touch(node);
+        return true;
+    }
+
+    /**
+     * Returns an item from the cache. Marks the item as most recently used.
+     */
+    public get(key: K): V | undefined {
+        const node = this.map.get(key);
+        if (!node) return undefined;
+        this.touch(node);
+        return node.value;
+    }
+
+    /**
+     * Adds an item to the cache. A newly added item is set as the most recently used.
+     */
+    public set(key: K, value: V): void {
+        try {
+            const existing = this.map.get(key);
+            if (existing) {
+                existing.value = value;
+                this.map.set(key, existing);
+                this.touch(existing);
+                return;
+            }
+
+            const node: LruNode<K, V> = { key, value, prev: null, next: null };
+            this.map.set(key, node);
+            this.append(node);
+
+            if (this.map.size > this.capacity && this.head) {
+                const lru = this.head;
+                this.unlink(lru);
+                this.map.delete(lru.key);
+            }
+        } catch (error) {
+            logger.warn("LruCache error", error);
+            this.clear();
+        }
+    }
+
+    /**
+     * Deletes an item from the cache.
+     */
+    public delete(key: K): void {
+        const node = this.map.get(key);
+        if (!node) return;
+        this.map.delete(key);
+        this.unlink(node);
+    }
+
+    /**
+     * Clears all items from the cache.
+     */
+    public clear(): void {
+        this.map.clear();
+        this.head = null;
+        this.tail = null;
+    }
+
+    /**
+     * Returns an iterator over the cached values in Map insertion order for the surviving keys.
+     */
+    public *values(): IterableIterator<V> {
+        for (const node of this.map.values()) {
+            yield node.value;
+        }
+    }
+
+    private touch(node: LruNode<K, V>): void {
+        if (node === this.tail) return;
+        this.unlink(node);
+        this.append(node);
+    }
+
+    private append(node: LruNode<K, V>): void {
+        node.prev = this.tail;
+        node.next = null;
+        if (this.tail) {
+            this.tail.next = node;
+        } else {
+            this.head = node;
+        }
+        this.tail = node;
+    }
+
+    private unlink(node: LruNode<K, V>): void {
+        if (node.prev) {
+            node.prev.next = node.next;
+        } else if (this.head === node) {
+            this.head = node.next;
+        }
+        if (node.next) {
+            node.next.prev = node.prev;
+        } else if (this.tail === node) {
+            this.tail = node.prev;
+        }
+        node.prev = null;
+        node.next = null;
+    }
+}

