import { logger } from "matrix-js-sdk/src/logger";

interface Entry<K, V> {
    key: K;
    value: V;
    prev?: Entry<K, V>;
    next?: Entry<K, V>;
}

/**
 * Least Recently Used cache implemented via a key lookup map and a doubly linked list.
 * The head of the list is the least recently used item, the tail the most recently used.
 */
export class LruCache<K, V> {
    private readonly map = new Map<K, Entry<K, V>>();
    private head?: Entry<K, V>;
    private tail?: Entry<K, V>;

    public constructor(private readonly capacity: number) {
        if (capacity < 1) {
            throw new Error("Cache capacity must be at least 1");
        }
    }

    /**
     * Check whether the cache contains an item under this key. Marks the item as most recently used.
     */
    public has(key: K): boolean {
        const entry = this.map.get(key);
        if (!entry) return false;
        this.moveToTail(entry);
        return true;
    }

    /**
     * Returns an item from the cache. Marks the item as most recently used.
     */
    public get(key: K): V | undefined {
        const entry = this.map.get(key);
        if (!entry) return undefined;
        this.moveToTail(entry);
        return entry.value;
    }

    /**
     * Adds an item to the cache. A newly added item is set as the most recently used.
     */
    public set(key: K, value: V): void {
        try {
            const existing = this.map.get(key);
            if (existing) {
                existing.value = value;
                this.moveToTail(existing);
                return;
            }

            const entry: Entry<K, V> = { key, value };
            this.map.set(key, entry);
            this.appendToTail(entry);

            if (this.map.size > this.capacity && this.head) {
                const oldest = this.head;
                this.unlink(oldest);
                this.map.delete(oldest.key);
            }
        } catch (error) {
            logger.warn("LruCache error", error);
            this.clear();
        }
    }

    /**
     * Deletes an item from the cache.
     */
    public delete(key: K): void {
        const entry = this.map.get(key);
        if (!entry) return;
        this.unlink(entry);
        this.map.delete(key);
    }

    /**
     * Clears all items from the cache.
     */
    public clear(): void {
        this.map.clear();
        this.head = undefined;
        this.tail = undefined;
    }

    /**
     * Returns an iterator over the cached values in Map insertion order for the surviving keys.
     */
    public *values(): IterableIterator<V> {
        for (const entry of this.map.values()) {
            yield entry.value;
        }
    }

    private appendToTail(entry: Entry<K, V>): void {
        entry.prev = this.tail;
        entry.next = undefined;
        if (this.tail) {
            this.tail.next = entry;
        } else {
            this.head = entry;
        }
        this.tail = entry;
    }

    private unlink(entry: Entry<K, V>): void {
        if (entry.prev) {
            entry.prev.next = entry.next;
        } else {
            this.head = entry.next;
        }
        if (entry.next) {
            entry.next.prev = entry.prev;
        } else {
            this.tail = entry.prev;
        }
        entry.prev = undefined;
        entry.next = undefined;
    }

    private moveToTail(entry: Entry<K, V>): void {
        if (entry === this.tail) return;
        this.unlink(entry);
        this.appendToTail(entry);
    }
}
