import { IMatrixProfile, MatrixClient, MatrixEvent, RoomMember, RoomMemberEvent } from "matrix-js-sdk/src/matrix";
import { logger } from "matrix-js-sdk/src/logger";

import { LruCache } from "../utils/LruCache";

const CACHE_SIZE = 500;

/**
 * Cached access to user profiles, with invalidation on membership changes.
 */
export class UserProfilesStore {
    // all fetched profiles
    private readonly profiles = new LruCache<string, IMatrixProfile | null>(CACHE_SIZE);
    // profiles of users who share at least one room with the current user
    private readonly knownProfiles = new LruCache<string, IMatrixProfile | null>(CACHE_SIZE);

    public constructor(private readonly client: MatrixClient) {
        this.client.on(RoomMemberEvent.Membership, this.onMembership);
    }

    /**
     * Synchronously get a profile from the store cache.
     * @returns the profile if cached, null if it does not exist, undefined if not cached.
     */
    public getProfile(userId: string): IMatrixProfile | null | undefined {
        return this.profiles.get(userId);
    }

    /**
     * Synchronously get a profile from the known-users cache.
     * @returns the profile if cached, null if it does not exist, undefined if not cached.
     */
    public getOnlyKnownProfile(userId: string): IMatrixProfile | null | undefined {
        return this.knownProfiles.get(userId);
    }

    /**
     * Asynchronously fetch a profile from the API and cache it.
     */
    public async fetchProfile(userId: string): Promise<IMatrixProfile | null> {
        try {
            const profile = await this.client.getProfileInfo(userId);
            this.profiles.set(userId, profile);
            return profile;
        } catch (error) {
            logger.warn(`Could not fetch profile for ${userId}`, error);
            this.profiles.set(userId, null);
            return null;
        }
    }

    /**
     * Asynchronously fetch a profile for a known user (one sharing a room with us).
     * @returns undefined if the user is not known, otherwise the profile or null.
     */
    public async fetchOnlyKnownProfile(userId: string): Promise<IMatrixProfile | null | undefined> {
        const isKnown = this.client.getRooms().some((room) => !!room.getMember(userId));
        if (!isKnown) return undefined;

        try {
            const profile = await this.client.getProfileInfo(userId);
            this.knownProfiles.set(userId, profile);
            return profile;
        } catch (error) {
            logger.warn(`Could not fetch known profile for ${userId}`, error);
            this.knownProfiles.set(userId, null);
            return null;
        }
    }

    private onMembership = (_event: MatrixEvent, member: RoomMember): void => {
        const displayName = member.rawDisplayName;
        const avatarUrl = member.getMxcAvatarUrl();
        this.invalidateIfChanged(this.profiles, member.userId, displayName, avatarUrl);
        this.invalidateIfChanged(this.knownProfiles, member.userId, displayName, avatarUrl);
    };

    private invalidateIfChanged(
        cache: LruCache<string, IMatrixProfile | null>,
        userId: string,
        displayName: string | undefined,
        avatarUrl: string | undefined,
    ): void {
        const cached = cache.get(userId);
        if (!cached) return;
        if (cached.displayname !== displayName || cached.avatar_url !== avatarUrl) {
            cache.delete(userId);
        }
    }
}
