+import { MatrixClient, RoomStateEvent } from "matrix-js-sdk/src/matrix";
+
+import { VoiceBroadcastInfoEventContent, VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";
+import { VoiceBroadcastRecording } from "../models/VoiceBroadcastRecording";
+import { VoiceBroadcastRecordingsStore } from "../stores/VoiceBroadcastRecordingsStore";
+
+export const startNewVoiceBroadcastRecording = async (
+    roomId: string,
+    client: MatrixClient,
+    recordingsStore: VoiceBroadcastRecordingsStore,
+): Promise<VoiceBroadcastRecording> => {
+    const userId = client.getUserId();
+    const room = client.getRoom(roomId);
+    let infoEventId: string | undefined;
+
+    return new Promise<VoiceBroadcastRecording>((resolve, reject) => {
+        const onRoomStateEvents = () => {
+            if (!infoEventId) return;
+            const infoEvent = room.currentState.getStateEvents(VoiceBroadcastInfoEventType, userId);
+            if (!infoEvent || infoEvent.getId() !== infoEventId) return;
+
+            room.off(RoomStateEvent.Events, onRoomStateEvents);
+            const recording = new VoiceBroadcastRecording(infoEvent, client);
+            recordingsStore.setCurrent(recording);
+            resolve(recording);
+        };
+
+        room.on(RoomStateEvent.Events, onRoomStateEvents);
+
+        client.sendStateEvent(
+            roomId,
+            VoiceBroadcastInfoEventType,
+            {
+                state: VoiceBroadcastInfoState.Started,
+                chunk_length: 300,
+            } as VoiceBroadcastInfoEventContent,
+            userId,
+        ).then(({ event_id: eventId }) => {
+            infoEventId = eventId;
+            // the event may already have been seen before the id was known
+            onRoomStateEvents();
+        }, reject);
+    });
+};

