+import { MatrixClient, MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+import {
+    VoiceBroadcastInfoEventContent,
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "liveness_changed",
+}
+
+interface EventMap {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (state: VoiceBroadcastInfoState) => void;
+}
+
+export class VoiceBroadcastRecording extends TypedEventEmitter<VoiceBroadcastRecordingEvent, EventMap> {
+    private _state: VoiceBroadcastInfoState;
+
+    public constructor(public readonly infoEvent: MatrixEvent, private client: MatrixClient) {
+        super();
+        this._state = this.getInitialState();
+    }
+
+    public get state(): VoiceBroadcastInfoState {
+        return this._state;
+    }
+
+    private getInitialState(): VoiceBroadcastInfoState {
+        const relations = this.client
+            .getRoom(this.infoEvent.getRoomId())
+            ?.getUnfilteredTimelineSet()
+            ?.relations?.getChildEventsForEvent(
+                this.infoEvent.getId(),
+                RelationType.Reference,
+                VoiceBroadcastInfoEventType,
+            )
+            ?.getRelations();
+
+        const stopped = (relations ?? []).some(
+            (event: MatrixEvent) => event.getContent()?.state === VoiceBroadcastInfoState.Stopped,
+        );
+
+        return stopped ? VoiceBroadcastInfoState.Stopped : VoiceBroadcastInfoState.Started;
+    }
+
+    private setState(state: VoiceBroadcastInfoState): void {
+        this._state = state;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged, state);
+    }
+
+    public async stop(): Promise<void> {
+        this.setState(VoiceBroadcastInfoState.Stopped);
+
+        const content: VoiceBroadcastInfoEventContent = {
+            state: VoiceBroadcastInfoState.Stopped,
+            ["m.relates_to"]: {
+                rel_type: RelationType.Reference,
+                event_id: this.infoEvent.getId(),
+            },
+        };
+
+        await this.client.sendStateEvent(
+            this.infoEvent.getRoomId(),
+            VoiceBroadcastInfoEventType,
+            content,
+            this.client.getUserId() as string,
+        );
+    }
+}
