import { MatrixClient } from "matrix-js-sdk/src/matrix";
import { RoomStateEvent } from "matrix-js-sdk/src/models/room-state";

import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";
import { VoiceBroadcastRecording } from "../models";
import { VoiceBroadcastRecordingsStore } from "../stores";

export const startNewVoiceBroadcastRecording = async (
    roomId: string,
    client: MatrixClient,
    recordingsStore: VoiceBroadcastRecordingsStore,
): Promise<VoiceBroadcastRecording> => {
    const room = client.getRoom(roomId);
    if (!room) {
        throw new Error(`Room ${roomId} not found`);
    }

    const userId = client.getUserId()!;
    let infoEventId: string | undefined;
    let done = false;
    let resolveRecording: (recording: VoiceBroadcastRecording) => void = () => {};
    const recordingPromise = new Promise<VoiceBroadcastRecording>(resolve => {
        resolveRecording = resolve;
    });

    const onRoomStateEvents = () => {
        if (done) return;
        const event = room.currentState.getStateEvents(VoiceBroadcastInfoEventType, userId);
        if (!event || !infoEventId || event.getId() !== infoEventId) return;

        done = true;
        room.off(RoomStateEvent.Events, onRoomStateEvents);
        const recording = new VoiceBroadcastRecording(event, client);
        recordingsStore.setCurrent(recording);
        resolveRecording(recording);
    };

    room.on(RoomStateEvent.Events, onRoomStateEvents);

    const response = await client.sendStateEvent(
        roomId,
        VoiceBroadcastInfoEventType,
        {
            state: VoiceBroadcastInfoState.Started,
            chunk_length: 300,
        },
        userId,
    );
    infoEventId = response.event_id;
    // The info event may already be in room state by now
    onRoomStateEvents();

    return recordingPromise;
};
