import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";

export enum VoiceBroadcastRecordingEvent {
    StateChanged = "liveness_changed",
}

interface EventMap {
    [VoiceBroadcastRecordingEvent.StateChanged]: (state: VoiceBroadcastInfoState) => void;
}

export class VoiceBroadcastRecording extends TypedEventEmitter<VoiceBroadcastRecordingEvent, EventMap> {
    private _state: VoiceBroadcastInfoState;

    public constructor(
        public readonly infoEvent: MatrixEvent,
        private client: MatrixClient,
    ) {
        super();
        const related = client.getRoom(infoEvent.getRoomId())
            ?.getUnfilteredTimelineSet()
            ?.relations
            ?.getChildEventsForEvent(infoEvent.getId(), RelationType.Reference, VoiceBroadcastInfoEventType)
            ?.getRelations();
        this._state = related?.find((e: MatrixEvent) => {
            return e?.getContent()?.state === VoiceBroadcastInfoState.Stopped;
        }) ? VoiceBroadcastInfoState.Stopped : VoiceBroadcastInfoState.Started;
    }

    public get state(): VoiceBroadcastInfoState {
        return this._state;
    }

    public async stop(): Promise<void> {
        this._state = VoiceBroadcastInfoState.Stopped;
        this.emit(VoiceBroadcastRecordingEvent.StateChanged, VoiceBroadcastInfoState.Stopped);
        await this.client.sendStateEvent(
            this.infoEvent.getRoomId(),
            VoiceBroadcastInfoEventType,
            {
                state: VoiceBroadcastInfoState.Stopped,
                ["m.relates_to"]: {
                    rel_type: RelationType.Reference,
                    event_id: this.infoEvent.getId(),
                },
            },
            this.client.getUserId(),
        );
    }
}
