"""Simplistic ELF parser to get the QtWebEngine/Chromium versions.

I'm not proud of this, but it works. Ideally, Qt would expose the version in a
proper way, but it doesn't, so we need to read it from the library file.
"""

import re
import os
import glob
import enum
import struct
import dataclasses
from typing import IO, TYPE_CHECKING, Any, Optional, Tuple

from PyQt5.QtCore import QLibraryInfo

from qutebrowser.utils import utils

if TYPE_CHECKING:
    from qutebrowser.utils import version


class ParseError(Exception):

    """Raised when the ELF file could not be parsed."""


class Bitness(enum.Enum):

    """The bitness of the ELF file."""

    x32 = 1
    x64 = 2


class Endianness(enum.Enum):

    """The endianness of the ELF file."""

    little = 1
    big = 2


# Upper bound on how much we're willing to read for a single section.
_MAX_SECTION_SIZE = 1024 * 1024 * 1024

_VERSION_RE = re.compile(
    rb'QtWebEngine/(?P<webengine>[0-9]+\.[0-9]+(\.[0-9]+)*) '
    rb'Chrome/(?P<chromium>[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)'
)


def _unpack(fmt: str, fobj: IO[bytes]) -> Tuple[Any, ...]:
    """Read exactly struct.calcsize(fmt) bytes from fobj and unpack them."""
    size = struct.calcsize(fmt)
    data = fobj.read(size)
    if len(data) != size:
        raise ParseError(f"Expected {size} bytes, got {len(data)}")
    try:
        return struct.unpack(fmt, data)
    except struct.error as e:
        raise ParseError(str(e))


@dataclasses.dataclass
class Ident:

    """The ELF ident header (first 16 bytes of the file)."""

    bitness: Bitness
    endianness: Endianness
    version: int
    osabi: int
    abiversion: int

    _FORMAT = '<4sBBBBB7x'

    @classmethod
    def parse(cls, fobj: IO[bytes]) -> 'Ident':
        """Parse an ELF ident header from a file object."""
        magic, bitness_raw, endianness_raw, version, osabi, abiversion = _unpack(
            cls._FORMAT, fobj)

        if magic != b'\x7fELF':
            raise ParseError(f"Invalid magic {magic!r}")

        try:
            bitness = Bitness(bitness_raw)
        except ValueError:
            raise ParseError(f"Invalid bitness {bitness_raw}")

        try:
            endianness = Endianness(endianness_raw)
        except ValueError:
            raise ParseError(f"Invalid endianness {endianness_raw}")

        return cls(bitness=bitness, endianness=endianness, version=version,
                   osabi=osabi, abiversion=abiversion)


@dataclasses.dataclass
class Header:

    """The ELF header without the file identification."""

    typ: int
    machine: int
    version: int
    entry: int
    phoff: int
    shoff: int
    flags: int
    ehsize: int
    phentsize: int
    phnum: int
    shentsize: int
    shnum: int
    shstrndx: int

    _FORMATS = {
        Bitness.x64: '<HHIQQQIHHHHHH',
        Bitness.x32: '<HHIIIIIHHHHHH',
    }

    @classmethod
    def parse(cls, fobj: IO[bytes], bitness: Bitness) -> 'Header':
        """Parse an ELF header from a file object."""
        fmt = cls._FORMATS[bitness]
        values = _unpack(fmt, fobj)
        return cls(*values)


@dataclasses.dataclass
class SectionHeader:

    """An ELF section header."""

    name: int
    typ: int
    flags: int
    addr: int
    offset: int
    size: int
    link: int
    info: int
    addralign: int
    entsize: int

    _FORMATS = {
        Bitness.x64: '<IIQQQQIIQQ',
        Bitness.x32: '<IIIIIIIIII',
    }

    @classmethod
    def parse(cls, fobj: IO[bytes], bitness: Bitness) -> 'SectionHeader':
        """Parse an ELF section header from a file object."""
        fmt = cls._FORMATS[bitness]
        values = _unpack(fmt, fobj)
        return cls(*values)


def _section_header_at(fobj: IO[bytes], header: Header, index: int) -> SectionHeader:
    if index < 0 or index >= header.shnum:
        raise ParseError(f"Section index {index} out of range")
    fobj.seek(header.shoff + index * header.shentsize)
    return SectionHeader.parse(fobj, _bitness_of(header))


def _bitness_of(header: Header) -> Bitness:
    # Set by _parse_inner via attribute on the header instance.
    return header.__dict__['_bitness']  # type: ignore[no-any-return]


def _read_section_data(fobj: IO[bytes], sec: SectionHeader) -> bytes:
    if sec.size < 0 or sec.size > _MAX_SECTION_SIZE:
        raise ParseError(f"Invalid section size {sec.size}")
    fobj.seek(sec.offset)
    data = fobj.read(sec.size)
    if len(data) != sec.size:
        raise ParseError("Truncated section")
    return data


def _get_name(strtab: bytes, offset: int) -> str:
    if offset >= len(strtab):
        raise ParseError("Invalid string table offset")
    return strtab[offset:].split(b'\0', maxsplit=1)[0].decode('ascii')


def _parse_inner(fobj: IO[bytes]) -> 'version.WebEngineVersions':
    from qutebrowser.utils import version

    ident = Ident.parse(fobj)
    header = Header.parse(fobj, bitness=ident.bitness)
    header.__dict__['_bitness'] = ident.bitness

    if header.shstrndx >= header.shnum:
        raise ParseError("Invalid section header string table index")

    shstrtab_hdr = _section_header_at(fobj, header, header.shstrndx)
    strtab = _read_section_data(fobj, shstrtab_hdr)

    for i in range(header.shnum):
        sec = _section_header_at(fobj, header, i)
        name = _get_name(strtab, sec.name)
        if name != '.rodata':
            continue

        data = _read_section_data(fobj, sec)
        match = _VERSION_RE.search(data)
        if match is None:
            raise ParseError("No QtWebEngine version found in .rodata")

        webengine = utils.parse_version(match.group('webengine').decode('ascii'))
        chromium = match.group('chromium').decode('ascii')
        return version.WebEngineVersions(webengine=webengine, chromium=chromium,
                                         source='ELF')

    raise ParseError("No .rodata section found")


def _parse_from_file(fobj: IO[bytes]) -> 'version.WebEngineVersions':
    """Parse the QtWebEngine versions from an ELF file object.

    Raises ParseError on any kind of malformed/truncated/non-ELF input.
    """
    try:
        return _parse_inner(fobj)
