def clean_subject_text(v: str) -> str:
    """Strip, remove trailing dot, and tidy a subject value."""
    v = v.strip()
    if v:
        v = remove_trailing_dot(v).strip()
    if v:
        v = tidy_subject(v)
    return v


def read_person(field) -> str:
    name_and_date = []
    for k, v in field.get_subfields(['a', 'b', 'c', 'd']):
        v = '(' + v.strip('.() ') + ')' if k == 'd' else v.strip(' /,;:')
        if k == 'a' and re_flip_name.match(v):
            v = flip_name(v)
        name_and_date.append(v)
    return remove_trailing_dot(' '.join(name_and_date)).strip()


def read_org(field) -> str:
    """Single normalized org name built from the combined a+b+c+d subfields."""
    return clean_subject_text(' '.join(field.get_subfield_values('abcd')))


def read_event(field) -> str:
    v = ' '.join(j.strip() for i, j in field.get_all_subfields() if i not in 'vxyz')
