def _get_legacy_state(name):
    prefix, _, member = name.partition('_')
    enum_type = IteratingStates if prefix == 'ITERATING' else FailedStates
    if member not in enum_type.__members__:
        raise AttributeError("no legacy PlayIterator state named %r" % name)
    display.deprecated(
        'PlayIterator.%s is deprecated, use %s.%s instead' % (name, enum_type.__name__, member),
        version='2.14',
    )
    return enum_type[member]


