def _sanitize_keys_conditions(value, no_log_strings, ignore_keys, deferred_removals):
    """
    Helper function for :func:`sanitize_keys`.

    Returns scalars unchanged.  For containers, returns a new empty container of the
    same kind and records ``(old, new)`` in ``deferred_removals`` so that its
    contents can be copied (with keys sanitized) later.
    """
    if isinstance(value, (text_type, binary_type)):
        return value

    elif isinstance(value, Sequence):
        if isinstance(value, MutableSequence):
            new_value = type(value)()
        else:
            new_value = []  # Need a mutable value
        deferred_removals.append((value, new_value))
        return new_value

    elif isinstance(value, Set):
        if isinstance(value, MutableSet):
            new_value = type(value)()
        else:
            new_value = set()  # Need a mutable value
        deferred_removals.append((value, new_value))
        return new_value

    elif isinstance(value, Mapping):
        if isinstance(value, MutableMapping):
            new_value = type(value)()
        else:
            new_value = {}  # Need a mutable value
        deferred_removals.append((value, new_value))
        return new_value

    return value


def sanitize_keys(obj, no_log_strings, ignore_keys=frozenset()):
    """Sanitize the keys in a container object by removing no_log values from key names.

    This is a companion to :func:`remove_values`, which only redacts values.  Mapping
    keys are redacted at any depth:

    * a key matching a ``no_log_string`` in full is replaced with ``VALUE_SPECIFIED_IN_NO_LOG_PARAMETER``
    * a key containing a ``no_log_string`` has each match replaced with ``********``
    * a key which is wholly present in ``ignore_keys`` is returned unchanged

    Mapping values, scalar values and container types (list, set, mapping) are preserved.

    :arg obj: The container (or scalar) to sanitize.
    :arg no_log_strings: Iterable of strings whose occurrences must be removed from key names.
    :kw ignore_keys: Keys which are returned unchanged.
    :returns: A sanitized copy of ``obj``.
    """
    deferred_removals = deque()

    no_log_strings = [to_native(s, errors='surrogate_or_strict') for s in no_log_strings]
    new_value = _sanitize_keys_conditions(obj, no_log_strings, ignore_keys, deferred_removals)

    while deferred_removals:
        old_data, new_data = deferred_removals.popleft()
        if isinstance(new_data, Mapping):
            for old_key, old_elem in old_data.items():
                if old_key in ignore_keys:
                    new_key = old_key
                else:
                    new_key = _remove_values_conditions(old_key, no_log_strings, deque())
                new_elem = _sanitize_keys_conditions(old_elem, no_log_strings, ignore_keys, deferred_removals)
                new_data[new_key] = new_elem
        else:
            for elem in old_data:
                new_elem = _sanitize_keys_conditions(elem, no_log_strings, ignore_keys, deferred_removals)
                if isinstance(new_data, MutableSequence):
                    new_data.append(new_elem)
                elif isinstance(new_data, MutableSet):
                    new_data.add(new_elem)
                elif isinstance(new_data, list):
                    new_data.append(new_elem)
                elif isinstance(new_data, set):
                    new_data.add(new_elem)
                else:
                    raise TypeError('Unknown container type encountered when sanitizing keys')

    return new_value


